"""Helper utilities."""

def merge_intervals(intervals):
    """Merge overlapping or touching [start, end] intervals, sorted by start."""
    if not intervals:
        return []

    merged = [intervals[0]]
    for current in intervals[1:]:
        prev = merged[-1]
        # If current start is less than or equal to previous end, they overlap or touch
        if current[0] <= prev[1]:
            prev[1] = max(prev[1], current[1])
        else:
            merged.append(current)

    return merged
